reactiveclass Counter(env) {
	knownrebecs {
		Environment env;
	}

	statevars {
		int count;
	}

	Counter() {
		count = 0;
	}

	msgsrv Increment() {
		count = count + 1;
		env.ValueResponse(count);
	}

	msgsrv Decrement() {
		count = count - 1;
		env.ValueResponse(count);
	}

	msgsrv GetValue() {
		env.ValueResponse(count);
	}
}

reactiveclass Client(env, id) {
	knownrebecs {
		Environment env;
	}

	statevars {
		int clientId;
	}

	Client() {
		clientId = id;
	}

	msgsrv ValueResponse(int value) {
		env.printClientValue(clientId, value);
	}
}

